-- Exportação do catálogo Game Atlas para importação manual pelo phpMyAdmin.
-- Gerado em 2026-11-16T14:37:59.068Z com 178 fichas.
SET NAMES utf8mb4;
-- Catálogo editorial para fichas da wiki; não altera a tabela jogos/biblioteca.
CREATE TABLE IF NOT EXISTS wiki_jogos (
  id VARCHAR(180) NOT NULL PRIMARY KEY,
  nome VARCHAR(255) NOT NULL,
  ano_lancamento SMALLINT NULL,
  franquia VARCHAR(120) NULL,
  categoria VARCHAR(120) NULL,
  nota VARCHAR(20) NULL,
  capa_url TEXT NULL,
  fonte_url TEXT NULL,
  detalhes_json LONGTEXT NOT NULL,
  atualizado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX idx_wiki_nome (nome),
  INDEX idx_wiki_franquia (franquia),
  INDEX idx_wiki_ano (ano_lancamento)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE
  nome=VALUES(nome),
  ano_lancamento=VALUES(ano_lancamento),
  franquia=VALUES(franquia),
  categoria=VALUES(categoria),
  nota=VALUES(nota),
  capa_url=VALUES(capa_url),
  fonte_url=VALUES(fonte_url),
  detalhes_json=VALUES(detalhes_json);
