INSERT INTO wiki_jogos (id, nome, ano_lancamento, franquia, categoria, nota, capa_url, fonte_url, detalhes_json)
VALUES
  ('monster-hunter-world', 'Monster Hunter: World', '2018', 'Monster Hunter', 'Franquia principal / spin-off', '88', 'https://cdn.akamai.steamstatic.com/steam/apps/582010/library_600x900_2x.jpg', 'https://store.steampowered.com/app/582010/', '{"id":"monster-hunter-world","steamAppId":582010,"name":"Monster Hunter: World","originalName":"MONSTER HUNTER: WORLD","year":2018,"releaseDate":"8 ago. 2018","developer":"CAPCOM Co., Ltd.","publisher":"CAPCOM Co., Ltd.","franchise":"Monster Hunter","category":"Franquia principal / spin-off","genres":["Ação"],"platforms":["PC"],"modes":["Co-op"],"cover":"https://cdn.akamai.steamstatic.com/steam/apps/582010/library_600x900_2x.jpg","videos":[{"provider":"steam","id":"256769112","title":"191203_防衛隊派生武器_BP_STEAM版","kind":"TRAILER","src":"https://video.akamai.steamstatic.com/store_trailers/582010/256093/bfd68b8de9543f413783c6110b0057f817be3c71/1750555302/hls_264_master.m3u8?t=1578590997","thumbnail":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256769112/movie.293x165.jpg?t=1578590997"},{"provider":"steam","id":"256769709","title":"191203_防具_防衛隊αシリーズ_BP_STEAM版","kind":"TRAILER","src":"https://video.akamai.steamstatic.com/store_trailers/582010/257064/edc963db3125e2b1f9a39bdec19554ca8e0df38e/1750555479/hls_264_master.m3u8?t=1578591006","thumbnail":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256769709/movie.293x165.jpg?t=1578591006"},{"provider":"steam","id":"256765469","title":"191016_MHW_ICEBORNE_SteamPV_English_BP_1080_60p_DJCTQ12.mp4","kind":"TRAILER","src":"https://video.akamai.steamstatic.com/store_trailers/582010/249524/568b8611f1673daf4869a88dc439a324df285bae/1750555035/hls_264_master.m3u8?t=1578591199","thumbnail":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256765469/movie.293x165.jpg?t=1578591199"},{"provider":"steam","id":"256747418","title":"190318_MHW_steamPV_TW3_BP.mp4","kind":"TRAILER","src":"https://video.akamai.steamstatic.com/store_trailers/582010/217163/13fee19261dd1ed2dfdd08a4454302ac9a769425/1750554743/hls_264_master.m3u8?t=1578591421","thumbnail":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256747418/movie.293x165.jpg?t=1578591421"},{"provider":"steam","id":"256746428","title":"190318_MHW_steamPV_AC_BP.mp4","kind":"TRAILER","src":"https://video.akamai.steamstatic.com/store_trailers/582010/215391/0c75e48e7bd120147972c60c432d77e7e99f9398/1750554493/hls_264_master.m3u8?t=1578591532","thumbnail":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256746428/movie.293x165.jpg?t=1578591532"}],"screenshots":["https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/582010/ss_a262c53b8629de7c6547933dc0b49d31f4e1b1f1.1920x1080.jpg?t=1791439347","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/582010/ss_6b4986a37c7b5c185a796085c002febcdd5357b5.1920x1080.jpg?t=1791439347","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/582010/ss_0dfb20f6f09c196bfc317bd517dc430ed6e6a2a4.1920x1080.jpg?t=1791439347","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/582010/ss_25902a9ae6977d6d10ebff20b87e8739e51c5b8b.1920x1080.jpg?t=1791439347","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/582010/ss_681cc5358ec55a997aee9f757ffe8b418dc79a32.1920x1080.jpg?t=1791439347","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/582010/ss_ce69dc57e6e442c73d874f1b701f2e4af405fb19.1920x1080.jpg?t=1791439347"],"score":"88","tagline":"Bem-vindo a um novo mundo! Monster Hunter: World é o mais recente jogo da série e a derradeira experiência de caça. Usa todos os recursos à tua disposição para caçar monstros num mundo a transbordar de surpresas e adrenalina.","description":"Bem-vindo a um novo mundo! Entra na pele de um caçador e mata monstros ferozes num ecossistema repleto de vida, onde podes usar o ambiente e os seus variados habitantes para ganhar vantagem. Caça sozinho ou em modo cooperativo com até 3 outros jogadores, usa os materiais recolhidos dos inimigos caídos para criar novos equipamentos e prepara-te para enfrentar criaturas maiores e ainda mais ferozes! APRESENTAÇÃO\\n Descrição geral\\n Enfrenta monstros gigantescos em cenários épicos. \\n\\nEnquanto caçador, a tua missão é caçar monstros em todo o tipo de locais.\\nEnfrenta os monstros e obtém materiais que podes usar para criar armas e armaduras poderosas, de modo a caçares criaturas cada vez mais impressionantes.\\n\\nMonster Hunter: World é o mais recente jogo da série e a derradeira experiência de caça. Usa todos os recursos à tua disposição para caçar monstros num mundo a transbordar de surpresas e adrenalina.\\n\\n Contexto \\nUma vez por década, os dragões ancestrais atravessam o mar rumo a um território ao qual foi dado o nome de Novo Mundo, numa migração conhecida como a Travessia Ancestral.\\n\\nDe modo a averiguar este misterioso fenómeno, a Guilda formou uma Comissão de Investigação, cujos membros partiram em grandes números em direção ao Novo Mundo.\\n\\nQuando a Comissão envia a sua Quinta Frota em busca do gigantesco dragão ancestral conhecido como Zorah Magdaros, um caçador prepara-se para partir numa aventura mais extraordinária do que alguma vez imaginaram.\\n اECOSSISTEMA\\n Um mundo que respira vida \\nExistem diversos locais cheios de vida no jogo. Qualquer expedição neles deverá revelar descobertas curiosas. CAÇA\\n Um arsenal variado e um parceiro indispensável \\nO teu equipamento terá todos os recursos de que precisas para fazer crescer a tua reputação no Novo Mundo.\\n\\n O arsenal do caçador \\nTens catorze armas à tua disposição, cada uma delas com ataques e caraterísticas únicas.\\nAlguns caçadores esforçam-se por dominar uma única arma, enquanto outros preferem ter um bom nível com várias delas.\\n\\n Moscas batedoras \\nCada local é marcado por rastos de monstros, tal como pegadas e covas.\\nAs moscas batedoras irão lembrar-se do cheiro dos monstros e guiar-te até aos rastos mais próximos.\\nÀ medida que reúnes mais rastos, as moscas batedoras irão revelar mais informações.\\n\\n Fisga \\nA Fisga é indispensável para qualquer caçador, e podes carregá-la com as pedras e nozes de cada local.\\nTáticas de diversão, encontrar atalhos e não só, a Fisga pode ser usada de inúmeras maneiras e permite-te caçar usando novas e interessantes abordagens.\\n\\n Ferramentas especializadas \\nAs ferramentas especializadas desencadeiam efeitos impressionantes por tempo limitado, e podes equipar duas ao mesmo tempo.\\nSão fáceis de usar, podendo ser selecionadas e ativadas como qualquer outro item que leves nas tuas caçadas.\\n\\n Palicoes \\nOs Palicoes são os teus fiáveis companheiros nas caçadas e irão apoiar-te com vários tipos de habilidades, ofensivas, defensivas e podem até curar-te.\\nO Palico de um caçador junta-se à Quinta Frota com o mesmo orgulho que teria qualquer outro membro da Comissão.","highlights":["Ação","Co-op","Confira os trailers e as imagens da ficha."],"specs":null,"availability":"Lançado","sourceUrl":"https://store.steampowered.com/app/582010/","communityReview":{"platform":"Steam","scoreLabel":"Muito positivas","totalReviews":520983,"positive":462730,"negative":58253,"recommendPercent":89,"praise":"O ecossistema, a variedade de monstros e as caçadas cooperativas são os pontos mais celebrados.","caveat":"Parte dos jogadores relata caçadas longas e problemas técnicos pontuais, como sincronização de saves.","updatedAt":"2026-11-16T14:18:49.889Z","url":"https://store.steampowered.com/app/582010/?l=brazilian#app_reviews_hash"}}'),
  ('monster-hunter-rise', 'MONSTER HUNTER RISE', '2021', 'Monster Hunter', 'Franquia principal / spin-off', '86', 'https://cdn.akamai.steamstatic.com/steam/apps/1446780/library_600x900_2x.jpg', 'https://store.steampowered.com/app/1446780/', '{"id":"monster-hunter-rise","steamAppId":1446780,"name":"MONSTER HUNTER RISE","originalName":"MONSTER HUNTER RISE","year":2021,"releaseDate":"2021","developer":"CAPCOM Co., Ltd.","publisher":"CAPCOM Co., Ltd.","franchise":"Monster Hunter","category":"Franquia principal / spin-off","genres":["Ação"],"platforms":["PC"],"modes":["Co-op","Co-op online"],"cover":"https://cdn.akamai.steamstatic.com/steam/apps/1446780/library_600x900_2x.jpg","videos":[{"provider":"steam","id":"256850913","title":"SnowPC_PV1_54_BP_Steamストア用.mp4","kind":"TRAILER","src":"https://video.akamai.steamstatic.com/store_trailers/1446780/400072/23a86926546c0494379257b8cdc098438fa19dc1/1750688528/hls_264_master.m3u8?t=1633009807","thumbnail":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256850913/movie.293x165.jpg?t=1633009807"},{"provider":"steam","id":"256873105","title":"01_モンスター１本化_02_スレートなし_2K","kind":"TRAILER","src":"https://video.akamai.steamstatic.com/store_trailers/1446780/438782/f779e169cae6c7b06d7146d2ff1d904cffe9adf7/1750690841/hls_264_master.m3u8?t=1644458549","thumbnail":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256873105/movie.293x165.jpg?t=1644458549"}],"screenshots":["https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1446780/ss_f8249da14987e3c2d10fd4024736f28774c713da.1920x1080.jpg?t=1792548454","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1446780/ss_25686086b61ca88a859bc20d588682be92ab4d63.1920x1080.jpg?t=1792548454","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1446780/ss_d8d96313f1049c800d37a3fc521f06f926fca3ac.1920x1080.jpg?t=1792548454","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1446780/ss_961c552a99c5c64689bebf0e272b13c80947f644.1920x1080.jpg?t=1792548454","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1446780/ss_3f1a758231a78ab3cdd76c2f8f04d5bbec45faeb.1920x1080.jpg?t=1792548454","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1446780/ss_5a601d6ecee22fcd0cb6142aec5ff7de1e1de091.1920x1080.jpg?t=1792548454"],"score":"86","tagline":"Aceita o desafio e junta-te à caça! Torna-te caçador, explora novos mapas e usa uma variedade de armas para derrotar monstros temíveis num enredo totalmente novo, no mais recente episódio da galardoada série Monster Hunter: Monster Hunter Rise.","description":"Aceita o desafio e junta-te à caça! Torna-te caçador, explora novos mapas e usa uma variedade de armas para derrotar monstros temíveis num enredo totalmente novo, no mais recente episódio da galardoada série Monster Hunter: Monster Hunter Rise. O lançamento para PC inclui ainda várias otimizações que melhoram os gráficos e o desempenho.\\n\\n Monstros ferozes com habitats únicos \\nCaça uma infinidade de monstros mortalmente ferozes e imprevisíveis. As recompensas não te são dadas de mão beijada. Esforça-te para aprender os movimentos únicos tanto dos monstros clássicos, como das novas criaturas inspiradas no folclore japonês, incluindo a icónica criatura Magnamalo.\\n\\n Escolhe a tua arma e mostra do que és capaz \\nTens à tua escolha 14 tipos de arma diferentes que te oferecem estilos de jogo distintos, seja a curto ou longo alcance. Carrega a Espada Grandiosa para um ataque devastador, derrota monstros em grande estilo graças à elegante Espada Longa, torna-te um furacão de lâminas mortífero com as velozes Lâminas Duplas, faz investidas com a implacável Lança, ou usa o Arco e Fuzilarcos para atacar à distância. Estes são apenas alguns dos tipos de arma disponíveis do jogo, pelo que decerto encontrarás o estilo de jogo perfeito para ti. \\n\\n Caça, recolhe e fabrica rumo ao topo da cadeia alimentar \\nPor cada monstro que caçares recebes materiais que te permitem criar novas armas e armaduras, assim como melhorar o teu equipamento. Volta ao mapa e caça monstros ainda mais ferozes para receberes as melhores recompensas! Podes alterar de arma a qualquer altura nas Caixas de Equipamento, por isso as possibilidades são infinitas!\\n\\n Derrota monstros a solo ou em equipa \\nNo Hunter Hub podes juntar-te a até três jogadores e enfrentar monstros nas missões multijogador. A dificuldade adapta-se à quantidade de jogadores, por isso os combates são sempre justos, quer seja a solo ou em equipa.\\n\\n Gráficos incríveis, velocidade de fotogramas desbloqueada e outras otimizações para PC \\nDesfruta de gráficos excecionais com até 4K de resolução, HDR com suporte para funcionalidades incluindo monitores ultrawide e uma velocidade de fotogramas desbloqueada para tornar a tua experiência muito mais imersiva. Obtém ainda acesso imediato a várias atualizações grátis que incluem novos monstros, missões, equipamento e muito mais.\\n\\n Desfruta de uma nova narrativa em Kamura Village \\nEste local sereno é habitado por vários aldeões empolgantes que vivem há demasiado tempo com medo da Rampage: um evento catastrófico no qual inúmeros monstros atacam a vila de uma vez. Agora, 50 anos após a última Rampage, vais ter de ajudar os aldeões a enfrentar este desafio.\\n\\nDesfruta de novas ações de caça com o Wirebug \\nOs Wirebugs fazem parte do conjunto de ferramentas do teu caçador. Disparam uma seda especial que te pode ajudar a subir paredes e atravessar mapas. Além disso, permitem-te sacar da cartola ataques especiais exclusivos dos 14 tipos de arma no jogo.\\n\\n Os Buddies estão aqui para ajudar \\nLembras-te dos felinos Palico das anteriores aventuras no Monster Hunter? Se gostaste deles, vais gostar ainda mais dos Palamute, os novos companheiros caninos.\\n\\n Causa estragos a controlar monstros \\nControla monstros furiosos graças à Wyvern Riding e causa imenso dano aos teus alvos! \\n\\n Defende-te das vagas de monstros na Rampage \\nProtege a Kamura Village das vagas de monstros num novo tipo de missão! Prepara-te para caçar monstros numa escala nunca antes vista!","highlights":["Ação","Co-op","Confira os trailers e as imagens da ficha."],"specs":null,"availability":"Lançado","sourceUrl":"https://store.steampowered.com/app/1446780/","communityReview":{"platform":"Steam","scoreLabel":"Muito positivas","totalReviews":128939,"positive":107831,"negative":21108,"recommendPercent":84,"praise":"O ritmo ágil do combate e as novas opções de mobilidade aparecem entre os elogios recorrentes.","caveat":"Algumas avaliações reclamam de problemas com saves, excesso de diálogos iniciais e ajustes para jogar online.","updatedAt":"2026-11-16T14:18:49.889Z","url":"https://store.steampowered.com/app/1446780/?l=brazilian#app_reviews_hash"}}'),
  ('monster-hunter-wilds', 'Monster Hunter Wilds', '2025', 'Monster Hunter', 'Franquia principal / spin-off', '—', 'https://cdn.akamai.steamstatic.com/steam/apps/2246340/library_600x900_2x.jpg', 'https://store.steampowered.com/app/2246340/', '{"id":"monster-hunter-wilds","steamAppId":2246340,"name":"Monster Hunter Wilds","originalName":"MONSTER HUNTER WILDS","year":2025,"releaseDate":"27 fev. 2025","developer":"CAPCOM Co., Ltd.","publisher":"CAPCOM Co., Ltd.","franchise":"Monster Hunter","category":"Franquia principal / spin-off","genres":["Ação","Aventura","RPG"],"platforms":["PC"],"modes":["Co-op","Co-op online"],"cover":"https://cdn.akamai.steamstatic.com/steam/apps/2246340/library_600x900_2x.jpg","videos":[{"provider":"steam","id":"257283353","title":"10_MHWilds_TU4.5_Multi_BP_DJCTQ_1080p","kind":"TRAILER","src":"https://video.akamai.steamstatic.com/store_trailers/2246340/877879669/a0387fc74550c7820a80e9bee61bb4fe0bccce95/1770702385/hls_264_master.m3u8?t=1770710673","thumbnail":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/257283353/f56fc8e58afb3467141df79a3f449fab20649949/movie_600x337.jpg?t=1770710673"},{"provider":"steam","id":"257247857","title":"09_MHWilds_TU4_Multi_BP_DJCTQ_1080p","kind":"TRAILER","src":"https://video.akamai.steamstatic.com/store_trailers/2246340/2047555566/2c661d0eeeb0444dc05f34076a978cd5e5fecd5f/1765505303/hls_264_master.m3u8?t=1765526399","thumbnail":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/257247857/a65be8c16e8d198844dfe817412b441c5d1f352e/movie_600x337.jpg?t=1765526399"},{"provider":"steam","id":"257205920","title":"09_MHWilds_TU3_Multi_BP_DJCTQ_1080p","kind":"TRAILER","src":"https://video.akamai.steamstatic.com/store_trailers/2246340/1129824090/70ff021e64bbc21323c4ae2b37617136531d7d58/1758776377/hls_264_master.m3u8?t=1758783943","thumbnail":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/257205920/9dfa3c12cb51aefbc31d546a232181be24c19322/movie_600x337.jpg?t=1758783943"},{"provider":"steam","id":"257162160","title":"09_MHWilds_TU2_Multi_BP_DJCTQ_1080p","kind":"TRAILER","src":"https://video.akamai.steamstatic.com/store_trailers/2246340/7617440/e2c05f60c6c7b69c3819da3888256a009893aa7b/1750990610/hls_264_master.m3u8?t=1750999180","thumbnail":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/257162160/7abdbb66cc73fe48c5d83286a334fb9e83c6bbe5/movie_600x337.jpg?t=1750999180"},{"provider":"steam","id":"257118561","title":"09_MHWilds_TU1_Multi_BP_1080p","kind":"TRAILER","src":"https://video.akamai.steamstatic.com/store_trailers/2246340/857811/6dd35abadf20e00134979081245c526b275a1cb4/1748036249/hls_264_master.m3u8?t=1742961795","thumbnail":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/257118561/d9f67f524a5de835fc81740acae8e4178c4dc8d9/movie_600x337.jpg?t=1742961795"}],"screenshots":["https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2246340/ss_31b5597fecf2d9a2904bc9bbf8011aacb18143db.1920x1080.jpg?t=1787549555","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2246340/ss_9245c1ede8c3fc2cd65e4890a74a01ef50b726da.1920x1080.jpg?t=1787549555","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2246340/ss_c722e74607ffda9a1472093ccc934f1bdde10ab8.1920x1080.jpg?t=1787549555","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2246340/ss_d439e321350c004c4d866c248019aefdc6a50600.1920x1080.jpg?t=1787549555","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2246340/ss_fa2361b39da8e8bde3cbc282879de97f2f3e57af.1920x1080.jpg?t=1787549555","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2246340/ss_c1dd8c8af4e0fd3bb233888b4155d94f7988debd.1920x1080.jpg?t=1787549555"],"score":"—","tagline":"A força da natureza é avassaladora e as paisagens transformam-se drasticamente em momentos. Esta é uma história sobre monstros, humanos e o desafio que é viver em harmonia num mundo de dualidades. Prepara-te para a derradeira experiência de caça no Monster Hunter Wilds.","description":"A força da natureza é avassaladora e as paisagens transformam-se drasticamente em momentos.\\n\\nEsta é uma história sobre monstros, humanos e o desafio que é viver em harmonia num mundo de dualidades.\\n\\nCumpre o teu dever enquanto Hunter. Caça e derrota monstros poderosos e obtém os materiais necessários para fabricar novas armas e armaduras resistentes, enquanto descobres a ligação entre o povo das Forbidden Lands e o sítio onde habitam.\\n\\nPrepara-te para a derradeira experiência de caça no Monster Hunter Wilds.\\n\\nHistória\\n\\nHá alguns anos, o jovem Nata foi resgatado na fronteira das Forbidden Lands, uma região inexplorada que a guilda ainda não investigou.\\n\\nApós ouvir o relato do rapaz sobre a fuga a um monstro misterioso que atacou a sua aldeia, a guilda organizou uma expedição às Forbidden Lands para investigar.\\n\\nComeça assim a jornada da expedição para investigar o monstro conhecido como \\"White Wraith\\" e para salvar o guardião sob ataque.\\n\\nUm mundo vivo\\n\\nNas Forbidden Lands, as paisagens podem mudar drasticamente, já que o clima varia constantemente e de forma abrupta. Durante os rigorosos períodos de escassez e as perigosas intempéries, os monstros, famintos, saem em matilhas para caçar. Já nos períodos de abundância, a vida selvagem é rica e diversa.\\n\\nMonstros\\n\\nOs monstros que aqui habitam viram-se forçados a recorrer às suas características únicas para se adaptarem às alterações repentinas e sobreviver.\\n\\nDurante o período de intempérie, poderás até vislumbrar os monstros poderosos que estão no topo da cadeia alimentar.\\n\\nCaça\\n\\nÀ medida que o mundo à sua volta muda, os hunters e as suas táticas também precisam de evoluir. Não estão limitados à sua vasta gama de armas e armaduras... A própria arte da caça transformou-se e os hunters aprendem a antecipar o comportamento dos monstros e a familiarizar-se com o ambiente onde habitam.\\n\\nO Focus Mode acrescenta uma nova dimensão à caça. Direciona os teus ataques ou defesas e utiliza Focus Strikes para desferir ataques especiais que causam danos elevados a feridas e pontos fracos.\\n\\nPersonagens\\n\\nDesde parceiros de caça a membros da expedição, serão vários aqueles que te apoiarão na tua jornada.","highlights":["Ação","Aventura","Co-op","Confira os trailers e as imagens da ficha."],"specs":null,"availability":"Lançado","sourceUrl":"https://store.steampowered.com/app/2246340/","communityReview":{"platform":"Steam","scoreLabel":"Mistas","totalReviews":335487,"positive":167594,"negative":167893,"recommendPercent":50,"praise":"A ação de caça e o mundo vivo atraem quem procura uma experiência Monster Hunter mais recente.","caveat":"As avaliações críticas destacam desempenho no PC, travamentos e o ritmo da narrativa.","updatedAt":"2026-11-16T14:18:49.889Z","url":"https://store.steampowered.com/app/2246340/?l=brazilian#app_reviews_hash"}}'),
