ce9da5b3efe4be53c019bdd53cbfa72dc/movie_600x337.jpg?t=1788959174"},{"provider":"steam","id":"257395628","title":"No Man''s Sky 10th Anniversary Trailer","kind":"TRAILER","src":"https://video.akamai.steamstatic.com/store_trailers/275850/1483384318/7dd87a3225e877165ecd7b1c5d733e2f6c2f5bd3/1786365111/hls_264_master.m3u8?t=1786366883","thumbnail":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/257395628/5e869dff3dcec0bbed1c4f5c9833bf412ea04554/movie_600x337.jpg?t=1786366883"},{"provider":"steam","id":"257342704","title":"No Man''s Sky The Swarm Trailer","kind":"TRAILER","src":"https://video.akamai.steamstatic.com/store_trailers/275850/1357812463/db664a7c182f435166c7e128e51849825a5a6a5a/1779704885/hls_264_master.m3u8?t=1779887225","thumbnail":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/257342704/7ec259a39f3f7f5c42f7a621599fb55d002c8fcf/movie_600x337.jpg?t=1779887225"}],"screenshots":["https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/275850/7d45478fbac8b1a41172adf8e598784a7d04b41d/ss_7d45478fbac8b1a41172adf8e598784a7d04b41d.1920x1080.jpg?t=1793196605","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/275850/53afb343452e839000d5eab38d0656fcdad9547b/ss_53afb343452e839000d5eab38d0656fcdad9547b.1920x1080.jpg?t=1793196605","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/275850/6c2ddcffe192b0e155a69aa2a1dd3f33b863033d/ss_6c2ddcffe192b0e155a69aa2a1dd3f33b863033d.1920x1080.jpg?t=1793196605","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/275850/ss_d4884d4d208b3f6a3ecef898559da7a36102fc70.1920x1080.jpg?t=1793196605","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/275850/e9a343b9aaa51b91e14d1cbdf4b8dd11305f1377/ss_e9a343b9aaa51b91e14d1cbdf4b8dd11305f1377.1920x1080.jpg?t=1793196605","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/275850/cad26f1dc67d28327ccdabeecb68d5006ad5639b/ss_cad26f1dc67d28327ccdabeecb68d5006ad5639b.1920x1080.jpg?t=1793196605","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/275850/01a92e57a23e2196021091ccfa3e3eacb2c44639/ss_01a92e57a23e2196021091ccfa3e3eacb2c44639.1920x1080.jpg?t=1793196605","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/275850/227c7c49d81de5f77d260495885e433efaece06d/ss_227c7c49d81de5f77d260495885e433efaece06d.1920x1080.jpg?t=1793196605"],"score":"61","tagline":"Uma jornada de exploração espacial por planetas, criaturas e sistemas desconhecidos.","description":"Inspirado na aventura e imaginação que nós amamos nos clássicos de ficção científica, No Man''s Sky apresenta uma galáxia recheada de planetas e formas de vida únicas pronta para exploração, além de perigo e ação constante. Em No Man''s Sky, todas as estrelas são a luz de um sol distante orbitado por planetas cheios de vida, e você pode ir a qualquer um que escolher. Voe suavemente do espaço profundo até as superfícies planetárias sem telas de carregamento e sem limites. Nesse universo de geração processual infinita, você descobrirá lugares e criaturas que nenhum outro jogador viu antes, e talvez nunca verá. Embarque em uma jornada épica No centro da galáxia há um pulso irresistível que te atrai numa jornada até o mesmo para descobrir a verdadeira natureza do cosmo. Porém, ao enfrentar criaturas hostis e piratas ferozes, você entenderá que a morte tem um custo e que a sobrevivência é consequência das atualizações efetuadas na sua nave, suas armas e seu traje. Encontre seu destino Sua jornada em No Man''s Sky é somente sua. Você será um lutador que caça os mais fracos e rouba suas riquezas, ou enfrentará os piratas para ficar com o saque? O poder é seu se você atualizar sua nave em velocidade e armas. Ou um comerciante? Descubra fontes de riqueza em mundos esquecidos e explore tudo pelos maiores preços. Invista em mais espaço para cargas e você colherá grandes recompensas. Ou talvez um explorador? Vá além da fronteira conhecida e descubra lugares e coisas que ninguém nunca viu antes. Atualize seus motores para saltar ainda mais longe e fortaleça seu traje para sobreviver a ambientes tóxicos que matariam os desavisados. Compartilhe sua jornada A galáxia é um lugar vivo e pulsante. Comboios comerciais viajam entre estrelas, facções disputam territórios, piratas caçam os desavisados e a polícia está sempre patrulhando. Todos os outros jogadores vivem na mesma galáxia e você pode escolher compartilhar suas descobertas com eles no mapa que abrange o espaço conhecido. Talvez você verá os resultados das ações deles além dos seus...","highlights":["Explore planetas gerados proceduralmente e descubra formas de vida.","Construa bases, pilote naves e atravesse o espaço em busca de novos sistemas.","A aventura pode ser vivida só ou em grupo, em um universo compartilhado."],"specs":{"min":["Windows 10/11 (64-bit versions)","Intel Core i3","8 GB de RAM","Nvidia GTX 1060 3GB, AMD RX 470 4GB, Intel UHD graphics 630","15 GB de espaço disponível"],"recommended":["Não informado na página Steam","Não informado na página Steam","Não informado na página Steam","Não informado na página Steam","Não informado na página Steam"]},"availability":"Lançado","sourceUrl":"https://store.steampowered.com/app/275850/","dataSource":"Steam Store API","communityReview":{"platform":"Steam","scoreLabel":"Muito positivas","totalReviews":425559,"positive":363262,"negative":62297,"recommendPercent":85,"praise":"Jogadores elogiam a experiência e os elementos centrais da aventura.","caveat":"As avaliações também registram ressalvas que variam conforme o perfil de cada jogador.","updatedAt":"2026-11-16T14:29:40.605Z","url":"https://store.steampowered.com/app/275850/?l=brazilian#app_reviews_hash"}}'),
