mai.steamstatic.com/store_item_assets/steam/apps/257306745/3e269cd78056c895014bdde81a56a0913fdfb0b6/movie_600x337.jpg?t=1775747052"},{"provider":"steam","id":"257306749","title":"Sea of Thieves: 2026 Deluxe and Premium Editions Explained","kind":"TRAILER","src":"https://video.akamai.steamstatic.com/store_trailers/1172620/1980334430/9b4f41cf3e31718126d16fbae243606cb8046916/1774018273/hls_264_master.m3u8?t=1775747050","thumbnail":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/257306749/99709233aa72b400f77c043587dd6144f6f3bf2c/movie_600x337.jpg?t=1775747050"}],"screenshots":["https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1172620/ss_ec623c77d75dfa098c622b547b1ab21ad4cae0a8.1920x1080.jpg?t=1793617680","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1172620/275d2128c1f2c285341b2915c8d2b6d1a9a2ee4c/ss_275d2128c1f2c285341b2915c8d2b6d1a9a2ee4c.1920x1080.jpg?t=1793617680","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1172620/ef387b7eec7008a3706e8bb254a025680cbfb54d/ss_ef387b7eec7008a3706e8bb254a025680cbfb54d.1920x1080.jpg?t=1793617680","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1172620/de2eb59caf773847bb3906602295ce5c180879f7/ss_de2eb59caf773847bb3906602295ce5c180879f7.1920x1080.jpg?t=1793617680","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1172620/769ebfa9403815905c8d5a8b2a5cb83ea277dca1/ss_769ebfa9403815905c8d5a8b2a5cb83ea277dca1.1920x1080.jpg?t=1793617680","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1172620/ss_1d1989435afbc1ff8d8ec4d61283e41a30208337.1920x1080.jpg?t=1793617680","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1172620/56fcfc9d47f73a644f0f468dc33e5161373e2014/ss_56fcfc9d47f73a644f0f468dc33e5161373e2014.1920x1080.jpg?t=1793617680","https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1172620/ss_d431abb7120aa4a6cbc0be82e5a2cdcca62917b2.1920x1080.jpg?t=1793617680"],"score":"—","tagline":"Viva a fantasia pirata: navegue, procure tesouros e conte histórias com sua tripulação.","description":"Sea of Thieves oferece a experiência essencial de pirataria, da navegação e combate à exploração e pilhagem, você tem tudo para viver como um pirata e se tornar uma lenda. Como não há papéis definidos, você tem liberdade total para interagir com o mundo e os outros jogadores. Quer esteja em uma jornada de grupo ou navegando sozinho, você está destinado a encontrar outras tripulações nesta aventura de mundo compartilhado. Mas elas serão amigáveis ou hostis? E como você irá reagir? Descubra os mares Sea of Thieves incentiva você a escolher um ponto do horizonte e navegar até lá para descobrir tudo o que lhe aguarda, desde as passagens subterrâneas mais profundas até os picos mais altos das ilhas. Não importa o destino, sempre há algo para os jogadores curiosos descobrirem. A emoção nunca acaba Toda sessão de Sea of Thieves é imprevisível. Até mesmo uma simples Jornada até uma ilha tranquila pode se desenrolar em uma emboscada de esqueletos, uma batalha contra uma frota de Navios Fantasma ou uma busca implacável atrás de piratas rivais que fugiram com os seus espólios! Torne-se uma lenda Em sua jornada para se tornar uma Lenda Pirata, você acumulará espólios, construirá uma reputação e definirá um estilo pessoal único com suas recompensas conquistadas com tanto esforço. Aventureiro. Explorador. Conquistador. Que lenda você se tornará? Um jogo que está sempre crescendo A cada nova Temporada, Sea of Thieves ganha melhorias e expansões nos recursos do jogo, junto com uma programação de Eventos ao Vivo temáticos e recorrentes. Volte sempre para conferir o que chegou de novo enquanto avança pelos 50 níveis do Passe da Temporada gratuito para desbloquear várias recompensas. Bônus adicionais Os bônus digitais* adicionais incluem acesso à versão mais recente da Trilha Sonora Original de Sea of Thieves , o audiolivro Sea of Thieves: Athena''s Fortune e o e-book Rough Guide de Sea of Thieves . * Disponíveis para download em (requer login no site) ou por meio do Steam","highlights":["Navegue em grupo, dividindo tarefas entre velas, leme e canhões.","Caças ao tesouro, batalhas navais e encontros inesperados movimentam o mar.","O mundo compartilhado transforma cada viagem em uma história diferente."],"specs":{"min":["Windows 10 version 18362.0 or higher","Intel i3 4170 @ 3.7 GHz or AMD FX-6300 @ 3.5 GHz","8 GB de RAM","Nvidia GeForce GTX 660 or AMD Radeon R9 270","100 GB de espaço disponível"],"recommended":["Windows® 10 64-bit","Intel i7 4790 @4Ghz - AMD Ryzen 5 1600 @3.6Ghz","16 GB de RAM","Nvidia Geforce GTX 1080ti - AMD Radeon Rx Vega 64 - Intel A750","100 GB de espaço disponível"]},"availability":"Lançado","sourceUrl":"https://store.steampowered.com/app/1172620/","dataSource":"Steam Store API","communityReview":{"platform":"Steam","scoreLabel":"Muito positivas","totalReviews":374471,"positive":331618,"negative":42853,"recommendPercent":89,"praise":"Jogadores elogiam a experiência e os elementos centrais da aventura.","caveat":"As avaliações também registram ressalvas que variam conforme o perfil de cada jogador.","updatedAt":"2026-11-16T14:29:40.605Z","url":"https://store.steampowered.com/app/1172620/?l=brazilian#app_reviews_hash"}}'),
